runtime.database_clone:
set -e
{snippet:connection-string}
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none -d postgres <<'SQL'
{snippet:target-owned}
\getenv source_name STACK_SOURCE_DATABASE
\getenv source_user STACK_SOURCE_DATABASE_USER
SELECT format('DO $refuse$ BEGIN RAISE EXCEPTION %L; END $refuse$', 'the source database does not belong to its account; inspect existing state')
  WHERE :'source_name' IN ('postgres', 'template0', 'template1') OR NOT EXISTS (SELECT FROM pg_database
    WHERE datname = :'source_name' AND NOT datistemplate
      AND datdba = (SELECT oid FROM pg_roles WHERE rolname = :'source_user' AND NOT rolsuper))\gexec
SQL
status=0
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none -d postgres <<'SQL' || status=$?
\getenv database_name STACK_DATABASE
\getenv database_user STACK_DATABASE_USER
\getenv source_name STACK_SOURCE_DATABASE
SELECT format('DROP DATABASE IF EXISTS %I WITH (FORCE)', :'database_name')\gexec
ALTER DATABASE :"source_name" ALLOW_CONNECTIONS false;
SELECT count(pg_terminate_backend(pid)) AS terminated FROM pg_stat_activity
  WHERE datname = :'source_name' AND pid <> pg_backend_pid() \gset
SELECT format('CREATE DATABASE %I TEMPLATE %I OWNER %I ALLOW_CONNECTIONS false', :'database_name', :'source_name', :'database_user')\gexec
SQL
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none -d postgres <<'SQL'
\getenv source_name STACK_SOURCE_DATABASE
ALTER DATABASE :"source_name" ALLOW_CONNECTIONS true;
SQL
[ "$status" -eq 0 ] || exit "$status"
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none -d postgres <<'SQL'
\getenv database_name STACK_DATABASE
REVOKE ALL ON DATABASE :"database_name" FROM PUBLIC;
ALTER DATABASE :"database_name" ALLOW_CONNECTIONS true;
SQL
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none -d "$STACK_DATABASE" <<'SQL'
SET search_path = pg_catalog;
\getenv database_user STACK_DATABASE_USER
\getenv source_user STACK_SOURCE_DATABASE_USER
SELECT set_config('stack.database_user', :'database_user', false), set_config('stack.source_user', :'source_user', false) \gset
DO $reassign$
DECLARE
  database_user text := current_setting('stack.database_user');
  source_user text := current_setting('stack.source_user');
  kept text[];
  kept_database text;
BEGIN
  SELECT coalesce(array_agg(datname), '{}') INTO kept FROM pg_database
    WHERE datdba = (SELECT oid FROM pg_roles WHERE rolname = source_user) AND datname <> current_database();
  EXECUTE format('REASSIGN OWNED BY %I TO %I', source_user, database_user);
  FOREACH kept_database IN ARRAY kept LOOP
    EXECUTE format('ALTER DATABASE %I OWNER TO %I', kept_database, source_user);
  END LOOP;
END
$reassign$;
SQL

