snippets.connection-string:
case "$STACK_DATABASE" in
  *=* | *://*) printf '%s\n' 'the database name would be read as a connection string' >&2; exit 1 ;;
esac

snippets.target-owned:
\getenv database_name STACK_DATABASE
\getenv database_user STACK_DATABASE_USER
SELECT set_config('stack.database_name', :'database_name', false), set_config('stack.database_user', :'database_user', false) \gset
DO $check$
DECLARE
  database_name text := current_setting('stack.database_name');
  database_user text := current_setting('stack.database_user');
  role_oid oid;
BEGIN
  SELECT oid INTO role_oid FROM pg_roles WHERE rolname = database_user AND NOT rolsuper;
  IF role_oid IS NULL THEN
    RAISE EXCEPTION 'the database account does not exist; run stack up to provision it';
  END IF;
  IF database_name IN ('postgres', 'template0', 'template1') OR EXISTS (SELECT FROM pg_database
    WHERE datname = database_name AND (datistemplate OR datdba <> role_oid)) THEN
    RAISE EXCEPTION 'database belongs to another owner; inspect existing state';
  END IF;
END
$check$;
